head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf11200";
scwin.std_cd_apct_tp_cd = null;
scwin.reg_button = null;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — stdCdApctTpCdList, applId, acntNo, feeProcsStatCd, sys_today

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "rd_stdCdApctTpCd", fn: function(){ return (!(String(((dma_pageContext.get("stdCdApctTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("stdCdApctTpCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_datefmt_cal_contrtStrtDd
 * @description 초기화 — datefmt cal contrt Strt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_contrtStrtDd = function () { $c.date.checkCalendarFormat("cal_contrtStrtDd", "yyyyMMdd"); };

