/**
 * @method
 * @name beforIsur
 * @description befor Isur 처리
 * @param {String} applId applId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.beforIsur = async function (applId) {
    let isur_cd = $c.util.getComponent('ipt_isurCd').getValue(); if (isur_cd == null) { isur_cd = ''; }
    if (isur_cd === '') {
        await $c.win.alert("발행기관 코드를 입력해 주세요.");
        return;
    }
    const url = "/stdcd/invest.do?method=bfReturnReAppl";
    const params = "isur_cd=" + isur_cd + "&applId=" + applId + "&menuId=11200";
    $.post(url, params, async function(obj) {
            if (obj === '') {
                await $c.win.alert("직전입력분 자료가 없습니다.");
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
                $c.util.getComponent('ipt_isuKorNm').setValue(jsonData.isu_kor_nm);
                $c.util.getComponent('ipt_isuEngNm').setValue(jsonData.isu_eng_nm);
                $c.util.getComponent('ipt_jntBzNm').setValue(jsonData.jnt_bz_nm);
                $c.util.getComponent('ipt_isuAmt').setValue(jsonData.isu_amt);
                if (jsonData.isu_amt != null) {
                    $c.util.getComponent('txt_isuAmtMoney').setValue($c.num.formatNumberKor(String(((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).getValue) ? ($('#ipt_isuAmt')[0]).getValue() : (((($('#ipt_isuAmt')[0]) && typeof ($('#ipt_isuAmt')[0]).val === 'function') ? ($('#ipt_isuAmt')[0]).val() : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).value !== undefined) ? ($('#ipt_isuAmt')[0]).value : ($('#ipt_isuAmt')[0]))))) == null ? '' : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).getValue) ? ($('#ipt_isuAmt')[0]).getValue() : (((($('#ipt_isuAmt')[0]) && typeof ($('#ipt_isuAmt')[0]).val === 'function') ? ($('#ipt_isuAmt')[0]).val() : ((($('#ipt_isuAmt')[0]) && ($('#ipt_isuAmt')[0]).value !== undefined) ? ($('#ipt_isuAmt')[0]).value : ($('#ipt_isuAmt')[0])))))).replace(/,/g, '')));
                    $c.num.formatNumber($('#ipt_isuAmt')[0]);
                }
                $('#slc_currTpCd').find('option[value="' + jsonData.curr_tp_cd + '"]').attr("selected", true);
                $('input[name=ipt_isuTpCd][value="' + jsonData.isu_tp_cd + '"]').attr("checked", true);
                $('input[name=ipt_invstContrtIsuMethdTpCd][value="' + jsonData.invst_contrt_isu_methd_tp_cd + '"]').attr("checked", true);
                $('input[name=crwfnd_yn][value="' + jsonData.crwfnd_yn + '"]').attr("checked", true);
                $c.util.getComponent('cal_contrtStrtDd').setValue($c.date.dateFormat(jsonData.contrt_strt_dd));
                $c.util.getComponent('cal_contrtEndDd').setValue($c.date.dateFormat(jsonData.contrt_end_dd));
                $c.util.getComponent('ipt_plRevrRelContn').setValue(jsonData.pl_revr_rel_contn);
                $c.util.getComponent('ipt_speclContrtContn').setValue(jsonData.specl_contrt_contn);
                $c.util.getComponent('dma_hiddenStore').set('onln_small_invst_isuprn_nm', jsonData.onln_small_invst_isuprn_nm);
                $c.util.getComponent('dma_hiddenStore').set('onln_small_invst_intm_bz_nm', jsonData.onln_small_invst_intm_bz_nm);
                $c.util.getComponent('dma_hiddenStore').set('hpage', jsonData.hpage);
                $c.util.getComponent('dma_hiddenStore').set('mrgn_adm_inst_cd', jsonData.mrgn_adm_inst_cd);
                $c.util.getComponent('dma_hiddenStore').set('mrgn_adm_inst_nm', jsonData.mrgn_adm_inst_nm);
                if (jsonData.std_cd_apct_tp_cd != null) {
                    const vl = jsonData.std_cd_apct_tp_cd.toString();
                    const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
                    if (tObj.length > 0) {
                        $(tObj)[0].checked = true;
                    }
                }
                if (jsonData.appl_com_nm != null) {
                    $c.util.getComponent('ipt_applComNm').setValue(jsonData.appl_com_nm.toString());
                }
                if (jsonData.apct_nm != null) {
                    $c.util.getComponent('ipt_apctNm').setValue(jsonData.apct_nm.toString());
                }
                if (jsonData.encryp_apct_email != null) {
                    const email = jsonData.encryp_apct_email.toString();
                    const emails = email.split("@");
                    if (emails.length > 0) {
                        $c.util.getComponent('ipt_encrypApctEmail1').setValue(emails[0]);
                    }
                    if (emails.length > 1) {
                        $c.util.getComponent('ipt_encrypApctEmail2').setValue(emails[1]);
                    }
                }
                if (jsonData.apct_tel_no != null) {
                    const tel = jsonData.apct_tel_no.toString();
                    const tels = tel.split("-");
                    if (tels.length > 0) {
                        $c.util.getComponent('ipt_apctTelNo1').setValue(tels[0]);
                    }
                    if (tels.length > 1) {
                        $c.util.getComponent('ipt_apctTelNo2').setValue(tels[1]);
                    }
                    if (tels.length > 2) {
                        $c.util.getComponent('ipt_apctTelNo3').setValue(tels[2]);
                    }
                }
                if (jsonData.apct_fax_no != null) {
                    const fax = jsonData.apct_fax_no.toString();
                    const faxs = fax.split("-");
                    if (faxs.length > 0) {
                        $c.util.getComponent('ipt_apctFaxNo1').setValue(faxs[0]);
                    }
                    if (faxs.length > 1) {
                        $c.util.getComponent('ipt_apctFaxNo2').setValue(faxs[1]);
                    }
                    if (faxs.length > 2) {
                        $c.util.getComponent('ipt_apctFaxNo3').setValue(faxs[2]);
                    }
                }
                if (jsonData.encryp_cellphone_no != null) {
                    const hp = jsonData.encryp_cellphone_no.toString();
                    const hps = hp.split("-");
                    if (hps.length > 0) {
                        $c.util.getComponent('ipt_apctHpNo1').setValue(hps[0]);
                    }
                    if (hps.length > 1) {
                        $c.util.getComponent('ipt_apctHpNo2').setValue(hps[1]);
                    }
                    if (hps.length > 2) {
                        $c.util.getComponent('ipt_apctHpNo3').setValue(hps[2]);
                    }
                }
                if (applId === "" || applId === "undefined") {
                    await $c.win.alert("직전 입력내용이 반영되었습니다");
                } else {
                    await $c.win.alert("기신청한 내용이 반영되었습니다.\n\r수정후 재신청하시기 바랍니다.");
                }
            }
    });
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
};
